#!/usr/bin/env python3
"""RV1 C — builds docs/reports/RV1-summary.md.
 · always: A (app rrgCompute vs tools/rrg_verify.py) on the fixed synthetic price set → per-symbol table + edge cases
 · if docs/reports/RV1-data.json exists (written by scripts/rrg_data_check.py in Actions): the real-data table (Yahoo raw closes, 23 symbols, D and W) + B findings
    python3 tools/rrg_report.py"""
import datetime as dt, json, os, subprocess, sys, tempfile
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np, rrg_verify as V

OUT = os.path.join(ROOT, 'docs', 'reports', 'RV1-summary.md'); DATA = os.path.join(ROOT, 'docs', 'reports', 'RV1-data.json')
ST = {'lead': 'Out ↗', 'weak': 'Out ↘', 'imp': 'Under ↗', 'lag': 'Under ↘', 'flat': 'Neutral'}
def s_(x): return x.get('err', '—')[:18] if 'err' in x else ST[x['quad']]
def f(x, d=2): return f'{x:.{d}f}'


def table(rows, syms, adj=None, tag=''):
    L = ['| Symbol | TF | app state | independent | match | raw (EMA spread %) | ratio | mom | days | adjusted-close state | changes with adjusted? |', '|---|---|---|---|---|---|---|---|---|---|---|']
    for s in syms:
        for tf, k in (('D', 'd'), ('W', 'w')):
            a, p = rows[s]['app'][k] if adj else rows[s][k], (rows[s]['py'][k] if adj else None)
            if p is None: p = PY[s][k]
            ok = ('err' in a and 'err' in p) or ('err' not in a and 'err' not in p and a['quad'] == p['quad'] and a['days'] == p['days'])
            j = rows[s]['adj'][k] if adj else None
            L.append(f"| {s} | {tf} | {s_(a)} | {s_(p)} | {'✓' if ok else '✗'} | {'' if 'err' in a else f(a['rsTrend'], 3)} | {'' if 'err' in a else f(a['ratio'])} | {'' if 'err' in a else f(a['mom'])} | {'' if 'err' in a else a['days']} | "
                     + (f"{s_(j)} | {'—' if 'err' in a or 'err' in j else ('no' if j['quad'] == a['quad'] else '**yes**')} |" if adj else 'n/a (synthetic: no dividends) | — |'))
    return L


cases = V.gen()
with tempfile.TemporaryDirectory() as d:
    cf = os.path.join(d, 'c.json'); json.dump(cases, open(cf, 'w'))
    APP = json.loads(subprocess.run(['node', os.path.join(ROOT, 'tools', 'rrg_app_run.js'), cf], capture_output=True, text=True, check=True).stdout)
PY = V.run(cases)['rows']; bad = V.cmp(APP, V.run(cases))
R = APP['rows']
L = [f'# RV1 — verify the RRG calculation, symbol by symbol (generated {dt.date.today()})', '',
     'Research + tests only. **No app behaviour changed, no data written, no API key.** Method: the app\'s own `rrgBuildRows → rrgCompute / rrgToWeekly` (extracted from `index.html` into node by `tools/rrg_app_run.js`, not re-typed) is compared with an independent pandas implementation written from the brief (`tools/rrg_verify.py`). Guard: `tests/rrg_verify_test.py` (in `tests/run_regression.sh`).', '',
     '## Verdict', '',
     f'- **Code correctness (A): the app computes what the formula says.** {len(R)} cases ({len([k for k in R if k.startswith(("midweek:", "friday:"))])} symbol×end-date runs + {len([k for k in R if k.startswith("edge:")])} edge cases) × Daily and Weekly → **{len(bad)} mismatches** in state, days, prevDays, date, raw, momRaw, ratio, mom, ε, δ (tolerance 1e-9).']
if os.path.exists(DATA):
    D = json.load(open(DATA)); n_app = len(D['mismatches'])
    L.append(f"- **Real data (B), as of {D['asof']}:** same comparison on Yahoo raw closes, 23 symbols × D/W → **{n_app} mismatches**.")
else:
    L.append('- **Real data (B): pending** — run the `rrg-data-check` Actions workflow (see the Run section); this file is regenerated by it and the sections below fill in.')
L += ['', '## A · Independent check (synthetic fixed set, 1,200 sessions, two end dates)', '',
      'Why synthetic: the check is about code, so the price set must be fixed and reproducible; seeded random walks correlated with a SPY-like path (seed 20261117). Real-data runs are section B.', '',
      '### Edge cases (app result · both implementations agree)', '', '| Case | Daily | Weekly | Note |', '|---|---|---|---|']
NOTE = {'edge:spy_vs_itself': 'rs ≡ 1 → SD 0 → "not classified" ✓', 'edge:synthetic_up_1.01^n': 'Outperforming ✓; D is "fading" because constant-rate outperformance has ~0 acceleration (see finding 4)',
        'edge:flat_series': 'rs ≡ 2 is NOT recognised as flat (see finding 3)', 'edge:missing_spy_day': 'intersection of dates → same as missing ETF day ✓', 'edge:missing_etf_day': 'same ✓',
        'edge:mismatch_last_date': '"Mismatched end dates · not classified" ✓', 'edge:mismatch_last_date_bench_behind': 'same, other direction ✓', 'edge:D_need_minus_1': '282 < 283 → error ✓', 'edge:D_need_exact': '283 = 26+252+5 → classified ✓',
        'edge:W_need_exact_82w': '82 weeks = 26+52+4 → classified ✓', 'edge:W_need_minus_1_81w': 'error ✓', 'edge:no_data': '"No data" ✓', 'edge:hysteresis_oscillating': 'rs oscillates around 1 (crosses ±ε repeatedly); states agree bar by bar',
        'edge:hysteresis_noise_zero_drift': 'zero-drift noise; states agree', 'edge:holiday_week_ends_wed_ref_next_week': 'week closed once the next week starts (no preview) ✓', 'edge:holiday_week_ends_wed_ref_same_week': 'still inside the week → preview ✓'}
for k, v in R.items():
    if not k.startswith('edge:'): continue
    L.append(f"| {k[5:]} | {s_(v['d'])} | {s_(v['w'])}{' (+preview ' + ST[v['w']['preview']['quad']] + ')' if 'preview' in v['w'] else ''} | {NOTE.get(k, 'last week has ' + k.split('_')[2] + ' session(s) → partial, preview only ✓' if k.startswith('edge:last_week') else 'quadrant reachable ✓' if k.startswith('edge:quadrant') else '')} |")
L += ['', '### Per symbol (synthetic set ending Wed 18 Nov 2026 — last week unfinished → Weekly state is the last closed week)', '']
SY = {s: R['midweek:' + s] for s in V.SYMS}; PYS = {s: PY['midweek:' + s] for s in V.SYMS}
PY = PYS
L += table(SY, V.SYMS)
L += ['', '## B · Data checks (real prices)', '']
if os.path.exists(DATA):
    D = json.load(open(DATA)); globals()['PY'] = {s: D['rows'][s]['py'] for s in D['syms']}
    L += [f"### Per symbol — Yahoo raw closes (split-adjusted, no dividends = what Twelve Data sends), as of {D['asof']}", ''] + table(D['rows'], D['syms'], adj=True)
    L += ['', f"Full B1–B4 tables (5-year % of days the state differs, partial-bar simulation, benchmark sanity): `docs/reports/RV1-data.md`.", '']
    mm = D['mismatches']
    L += ['### Mismatches (app vs independent, real closes)', ''] + ([f'- {" ".join(m)}' for m in mm] if mm else ['None.'])
    ch = [(s, tf) for s in D['syms'] for tf, k in (('D', 'd'), ('W', 'w')) if 'err' not in D['rows'][s]['app'][k] and 'err' not in D['rows'][s]['adj'][k] and D['rows'][s]['app'][k]['quad'] != D['rows'][s]['adj'][k]['quad']]
    L += ['', f"### Symbols whose state *today* changes with dividend-adjusted closes: {len(ch)} of {2 * len(D['syms'])} (symbol × TF)", '', ', '.join(f'{s} {tf}' for s, tf in ch) or 'none']
else:
    L.append('Not generated yet — needs the Actions run (Yahoo is rate-limited on the Mac). The workflow writes `RV1-data.md/json` and re-runs this script.')
L += ['', '## Mismatch list', '', 'Code (A): **none**. ' + ('Data (B): see above.' if os.path.exists(DATA) else 'Data (B): pending.'), 'Definition differences are listed as findings (not mismatches: both implementations agree on them).', '',
      '## Findings — each is a separate item for you to approve (nothing was changed)', '',
      '1. **Adjusted vs raw closes (data).** The app uses split-adjusted, not dividend-adjusted closes. RS = ETF ÷ SPY on raw prices drifts by the *yield difference* (an ETF paying 3–4 % vs SPY ~1.3 % loses ~2 %/yr of relative price that is not real underperformance). Effect size per symbol: `RV1-data.md` B1. *Proposed fix (needs approval):* fetch `adjusted=true` closes / use adjusted series for RS only (Twelve Data adjusts splits by default; dividend-adjust needs `adjust=all`), then bump `RRG_MODEL`.',
      '2. **Unfinished daily bar (code path).** Nothing in `rrgFetchBatch`/`rrgSeries`/`rrgBuildRows` drops a bar that is still trading; `rrgBarsFresh` only checks recency and `rrgCacheFresh` keeps a fetch for the rest of the ICT calendar day. A fetch between 21:30 and 04:00 ICT classifies on the partial bar, and a fetch after ~00:00 ICT keeps that partial result until the next ICT day (so it can outlive the US close by up to ~20 h). Friday partial bars are also treated as a finished week. Impact: `RV1-data.md` B2. *Proposed fix:* drop the last daily bar when its date is today in New York and the market is open (or `date >= ET today` before 16:15 ET); mark the card "as of last close".',
      '3. **Constant-but-not-1 relative strength is not detected as flat (code, low).** `sd > 0` is an exact test: rs ≡ 2 gives SD ≈ 1e-9 from float noise, so a state is produced from noise (case `flat_series`). Only rs ≡ 1 (SPY vs itself) returns "not classified". Not reachable with real ETFs. *Proposed fix:* relative tolerance `sd < 1e-9·|mean|` → not classified.',
      '4. **Definition note — constant-rate outperformance is "fading", not "strengthening".** SPY×1.01ⁿ is correctly *Outperforming* but the momentum leg (raw − raw[lag]) is ~0 once the EMA spread saturates, so ↗/↘ is noise-driven. The brief expected "strengthening"; the definition (momentum = change of the EMA spread) cannot give that for a constant growth rate. *No fix proposed* — only the expectation changes. Quadrants are reachable with an accelerating/decelerating rs (5/5 reached).',
      '5. **Definition note — history is recomputed with today\'s ε, δ.** ε and δ use the SD of the *last* window and are applied to the whole history, so "days in state" and previous-state length can change when SD changes, without any new price. Both implementations agree; it is how the spec reads. *No fix proposed* unless you want states frozen when first seen.',
      '6. **Dead ticker in `RRG_SYMS`: IRBO (data/config).** IRBO (iShares Robotics & AI) was delisted and replaced by ARTY (iShares Future AI & Tech) in Aug 2024 — Yahoo/Twelve Data return no rows for IRBO, so its card can never compute. *Proposed fix (needs approval, `RRG_SYMS` NOT changed yet):* replace IRBO with ARTY "AI & Tech" (and update `sector_etf` references). Caveat: the index changed in Aug 2024, so ARTY history before that is the old robotics index — the 126-bar history used for ε/δ and "days in state" mixes two indices for the first ~months. ARTY is included in the data check as an extra symbol (marked “(extra)”) so its result is visible; symbols with no data are listed under “No data (skipped)”.',
      '', '## Run', '',
      '- Local (A, offline): `python3 tests/rrg_verify_test.py` · included in `bash tests/run_regression.sh` together with `python3 scripts/rrg_data_check.py --selftest`.',
      '- **B needs you:** copy `scripts/rrg-data-check.workflow.yml` to `.github/workflows/rrg-data-check.yml` on `claude/rv1` (or main), then Actions → **rrg-data-check** → Run workflow. It writes `docs/reports/RV1-data.{md,json}` and regenerates this file (≈10–15 min).',
      '- B3 (Twelve Data vs Yahoo): export once in the browser console — `copy(JSON.stringify(ffState().rrg.rowsD.map(r=>({sym:r.sym,date:r.date,close:r.close}))))` — save as `docs/reports/RV1-td-export.json`, add `--td-export docs/reports/RV1-td-export.json` to the workflow step. Only closes, no key.']
open(OUT, 'w', encoding='utf-8').write('\n'.join(L) + '\n'); print('wrote', OUT, 'mismatches', len(bad))
